  if((product.imageUrl&&!/^(https:\/\/|\/images\/)/.test(product.imageUrl))||(product.productUrl&&!/^https:\/\//.test(product.productUrl)))throw Error(`${product.slug}: HTTPS 주소가 필요합니다.`);
