const priceTool=p=>p.slug!=='compare-unit-prices'?'':`<section class="price-tool"><h2>100ml당 가격 직접 계산하기</h2><p>두 상품의 실제 결제액과 전체 용량을 입력하세요. 같은 종류의 상품끼리 비교할 때 사용합니다.</p><form id="price-form"><div class="price-fields"><fieldset><legend>상품 A</legend><label>결제액 (원)<input name="priceA" type="number" min="1" step="1" required></label><label>전체 용량 (ml)<input name="volumeA" type="number" min="0.01" step="any" required></label></fieldset><fieldset><legend>상품 B</legend><label>결제액 (원)<input name="priceB" type="number" min="1" step="1" required></label><label>전체 용량 (ml)<input name="volumeB" type="number" min="0.01" step="any" required></label></fieldset></div><button type="submit">계산하기</button></form><p id="price-result" role="status" aria-live="polite"></p></section><script>document.getElementById('price-form').addEventListener('submit',function(e){e.preventDefault();const d=new FormData(this);const a=Number(d.get('priceA'))/Number(d.get('volumeA'))*100;const b=Number(d.get('priceB'))/Number(d.get('volumeB'))*100;const result=document.getElementById('price-result');if(!Number.isFinite(a)||!Number.isFinite(b)||a<=0||b<=0){result.textContent='0보다 큰 금액과 용량을 입력해 주세요.';return}result.textContent='100ml당 상품 A '+Math.round(a).toLocaleString('ko-KR')+'원, 상품 B '+Math.round(b).toLocaleString('ko-KR')+'원입니다. '+(Math.abs(a-b)<0.5?'단위가격이 거의 같습니다.':a<b?'상품 A의 단위가격이 낮습니다.':'상품 B의 단위가격이 낮습니다.')+' 필요한 양과 총지출도 함께 비교하세요.'});</script>`;
