const sortClient=`function sortItems(items,mode){const number=(node,key)=>{const value=node.dataset[key];return value===''||value===undefined?null:Number(value)};return [...items].sort((a,b)=>{const order=Number(a.dataset.order)-Number(b.dataset.order);if(mode==='registered')return order;const key=mode.startsWith('price-')?'price':'discount',av=number(a,key),bv=number(b,key);if(av===null)return bv===null?order:1;if(bv===null)return -1;return (mode==='price-low'?av-bv:bv-av)||order})}`;
