function won(n){return Number.isFinite(n)?n.toLocaleString('ko-KR')+'원':'미확인'}
function savings(p){
  if(!Number.isFinite(p.pxPrice)||!(p.officialPrice>0))return '쿠팡가 미확인 · 할인율 비교 불가';
  const gap=p.officialPrice-p.pxPrice;
  return gap>0?`쿠팡가 대비 ${(gap/p.officialPrice*100).toFixed(1)}% 저렴 · ${won(gap)} 차이`:gap<0?`쿠팡가 대비 ${(-gap/p.officialPrice*100).toFixed(1)}% 높음`:'쿠팡가와 같은 가격';
}
function compactSavings(p){
 if(!Number.isFinite(p.pxPrice)||!Number.isFinite(p.officialPrice))return '쿠팡가 미확인';
 const gap=p.officialPrice-p.pxPrice;
 return gap>0?`${Math.round(gap/p.officialPrice*100)}% 저렴 · ${won(gap)} 차이`:gap<0?`${won(-gap)} 높음`:'가격 동일';
}
