const productTabs=`<div class="category-tabs" role="tablist" aria-label="상품 품목">${categories.map((c,i)=>`<button type="button" role="tab" id="tab-${i}" aria-controls="product-panel" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}" data-category="${esc(c)}">${esc(c)} <span>${c==='전체'?products.length:products.filter(p=>categoryFor(p)===c).length}</span></button>`).join('')}</div>`;
const productTabScript='<script src="/product-catalog.js" type="module"></script>';
write('products/index.html',page('PX 상품 소개','품목별 PX가와 외부 구매가를 비교합니다.',`<section class="section product-section">${productSearch}${productTabs}<div class="product-filter-row"><div class="subcategory-control"><label for="product-subcategories">소분류</label><select id="product-subcategories" aria-controls="product-panel"><option value="">전체 소분류</option></select></div>${sortControls('product-sort')}</div><div id="product-panel" role="tabpanel" aria-labelledby="tab-0"><p id="product-results" class="product-results" role="status" aria-live="polite">${Math.min(latestProducts.length,10)}개 표시</p><div class="cards product-list">${latestProducts.slice(0,10).map((p,i)=>productCard(p).replace('data-category=',`${i>=10?'hidden ':''}data-order="${i}" data-search="${esc(String(p.name||'').normalize('NFC').toLocaleLowerCase('ko-KR'))}" data-comparable="${Number.isFinite(p.pxPrice)&&p.officialPrice>0}" data-category=`)).join('')}</div><p class="category-empty" hidden></p><nav id="product-pagination" class="product-pagination" aria-label="상품 페이지"></nav></div></section>${productTabScript}`,'/products/'));
for(const product of products){
  const productDescription=/(?:첨부|블로그|제공된|추천표)/.test(product.description)?`${product.name}. 상품의 가격과 용량·구성을 확인하고 비교하세요.`:product.description;
  const caption=/(?:첨부|블로그|제공된|추천표)/.test(product.imageNote||'')?'사진과 실제 상품의 규격·구성을 대조하세요.':product.imageNote||`${product.brand} 상품 페이지와 연결되는 상품 식별 이미지입니다. 실제 판매 구성은 별도로 확인하세요.`;
  const productVisual=product.imageRegion?`<figure class="article-figure official-figure">${scanPhoto(product)}<figcaption>${esc(caption)}</figcaption></figure>`:product.imageUrl?`<figure class="article-figure official-figure"><img ${productImageAttributes(product,{detail:true})} alt="${esc(product.brand)} ${esc(product.name)} 상품 사진" onerror="this.hidden=true;this.nextElementSibling.hidden=false">${productFallback(product)}<figcaption>${esc(caption)}</figcaption></figure>`:`<figure class="article-figure official-figure">${productFallback(product)}<figcaption>이미지 확인 중</figcaption></figure>`;
  const priceComparison=product.category==='면세주류'?`<section class="price-comparison" aria-label="면세 가격 기록"><h2>면세 가격</h2><div class="price-columns"><div><span>면세가</span><strong>${won(product.pxPrice)}</strong></div></div><p class="price-small">${esc(product.scopeNote||'2026년 면세주류 가격표에 기재된 금액입니다. 실제 가격과 재고는 매장에서 확인하세요.')}</p></section>`:`<section class="price-comparison" data-price-slug="${esc(product.slug)}" data-price-px="${product.pxPrice}" aria-label="상품 가격 비교"><h2>가격 비교</h2><div class="price-columns"><div><span>PX가</span><strong>${won(product.pxPrice)}</strong></div><div><span>쿠팡가</span><strong data-price-value>${won(product.officialPrice)}</strong></div>${Number.isFinite(product.vatExemptPrice)?`<div><span>부가세 면제 가격</span><strong>${won(product.vatExemptPrice)}</strong></div>`:''}${Number.isFinite(product.pxPromotionPrice)?`<div><span>할인가</span><strong>${won(product.pxPromotionPrice)}</strong></div>`:''}</div>${product.category==='주류'&&!Number.isFinite(product.officialPrice)?'':`<p class="price-result" data-price-result></p>`}</section>`;
  const productDeals=monthlyRecords.flatMap(m=>m.items.filter(i=>i.productSlug===product.slug).map(i=>({month:m.month,...i})));
  const monthComparisons=productDeals.map(i=>`<section class="price-comparison"><h2>${esc(i.month.replace('-','년 '))}월 할인 기록</h2><div class="price-columns"><div><span>기존가</span><strong>${won(i.regularPrice)}</strong></div><div><span>할인가</span><strong>${won(i.salePrice)}</strong></div></div><p class="price-result">${esc(dealSavingLabel(i))}</p><p>행사 적용 여부와 기간은 방문할 매장에서 확인하세요.</p><a href="/monthly/${esc(i.month)}/">월별 할인 목록</a></section>`).join('');
  const detailSections=(product.details||[]).filter(([heading])=>!/(?:첨부표별 가격|자료|출처|일반가|가격표 기록)/.test(heading)).map(([heading,body])=>{
    if(/납품일/.test(heading))body='납품 일정과 재고는 방문할 매장에서 확인하세요.';
    else if(/보관 및 기간/.test(heading))body='상품 포장에 표시된 보관 온도와 소비기한을 따르세요.';
    else if(/이런 상품|상품 정보/.test(heading)&&/(첨부|제공된|추천표)/.test(body))body=product.name+' 상품입니다. 실제 포장과 규격·구성을 확인하세요.';
    else body=cleanReferenceText(body);
    return body?`<section><h2>${esc(heading)}</h2><p>${esc(body)}</p></section>`:'';
  }).join('');
  const details=detailSections||'<section><h2>구매 전 확인</h2><p>상품의 정확한 규격·구성·사용 방법은 상품 포장에서 확인하세요.</p></section>';
  const reference=product.referencePrice?`<section class="price-comparison"><h2>일반 정가 비교</h2><div class="price-columns"><div><span>PX가</span><strong>${won(product.pxPrice)}</strong></div><div><span>일반 정가</span><strong>${won(product.referencePrice)}</strong></div></div><p class="price-small">동일한 규격과 구성인지 확인하세요.</p></section>`:'';
  const scope=product.scopeNote|| (product.imageRegion?'첨부 커피 음료표에 기재된 상품명·용량·PX가·보관 및 기간 표기를 정리했습니다. 시중 구매가와 현재 매장 가격·재고는 확인되지 않았으며 직접 사용한 후기는 아닙니다.':product.pxPrice?'PX가와 구매가의 비교입니다. 가격과 구성, 재고는 변동될 수 있으며 직접 사용한 후기는 아닙니다.':'직접 사용한 후기나 현재 PX 판매가격을 확인한 글이 아닙니다. 아래 링크는 상품 식별용이며 실제 판매 구성과 다를 수 있습니다.');
  write(`products/${product.slug}/index.html`,page(product.name,productDescription,`<article class="article"><a class="back" href="/products/">← 상품 소개</a><span class="eyebrow">${esc(categoryFor(product))} · 구매 전 확인</span><h1>${esc(product.name)}</h1><button class="favorite-detail" type="button" data-favorite="${esc(product.slug)}" data-favorite-name="${esc(product.name)}" aria-pressed="false"><span aria-hidden="true">♡</span> <span data-favorite-label>찜하기</span></button><p class="lead">${esc(productDescription)}</p>${monthComparisons}${priceComparison}${product.sourceLinks?.filter(s=>!isReferenceLink(s.url)).length?`<p class="price-small">${product.sourceLinks.filter(s=>!isReferenceLink(s.url)).map(s=>`<a href="${esc(productLinkUrl(s.url,product.name))}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join(' · ')}</p>`:''}${reference}${Object.hasOwn(product,'boxPrice')?`<section class="price-comparison"><h2>박스 가격</h2><div class="compact-prices"><div><span>박스가</span><strong>${product.boxPrice?won(product.boxPrice):'매장 확인'}</strong></div></div><p class="price-small">박스에 포함된 수량과 규격은 매장에서 확인하세요.</p><a href="/guides/px-liquor-vat-exemption/">주류 부가세 면제 안내</a></section>`:''}${productVisual}${details}${product.productUrl&&!isReferenceLink(product.productUrl)?`<a class="button" href="${esc(productLinkUrl(product.productUrl,product.name))}" target="_blank" rel="noopener noreferrer">${esc(product.productLinkLabel||product.brand+' 상품 정보')} ↗</a>`:''}</article>`,`/products/${product.slug}/`));
}
const shoppingPrice=p=>{const deal=monthly.items.find(i=>i.productSlug===p.slug);return deal&&monthly.month==='2026-10'?deal.salePrice:p.pxPrice;};
const favoriteProducts=[...products];
for(const m of [monthly,...monthlyRecords])for(const i of m.items){if(favoriteProducts.some(p=>p.slug===i.productSlug))continue;favoriteProducts.push({slug:i.productSlug,name:i.name,brand:'',category:i.category,imageUrl:i.imageUrl,imageThumbUrl:i.imageThumbUrl,imageSrcSet:i.imageSrcSet,imageWidth:i.imageWidth,imageHeight:i.imageHeight,imageThumbWidth:i.imageThumbWidth,imageThumbHeight:i.imageThumbHeight,pxPrice:i.salePrice,primaryLabel:'행사가',catalogVisible:false,href:'/monthly/'+m.month+'/items/'+i.productSlug+'/'});}

write('favorites-data.json',JSON.stringify(favoriteProducts.map(p=>({slug:p.slug,name:p.name,brand:p.brand,href:p.href||'/products/'+p.slug+'/',catalogVisible:p.catalogVisible!==false,primaryLabel:p.primaryLabel||null,category:categoryFor(p),productGroup:productGroup(p),subcategory:productSubcategory({...p,category:categoryFor(p)}),comparisonQuantity:p.comparisonQuantity||1,pxPrice:Number.isFinite(p.pxPrice)?p.pxPrice:null,shoppingPrice:Number.isFinite(shoppingPrice(p))?shoppingPrice(p):null,priceBasis:monthly.items.some(i=>i.productSlug===p.slug)?(p.primaryLabel||'행사가'):'PX가',officialPrice:Number.isFinite(p.officialPrice)?p.officialPrice:null,vatExemptPrice:p.vatExemptPrice||null,pxPromotionPrice:p.pxPromotionPrice||null,boxPrice:p.boxPrice||null,comparisonKind:p.comparisonKind||'sameBundle',priceSeller:p.priceSeller||'쿠팡가',priceCheckedAt:p.priceCheckedAt||null,imageUrl:p.imageRegion||p.imageKind==='priceSheet'?null:productImage(p),imageThumbUrl:p.imageThumbUrl,imageSrcSet:p.imageSrcSet,imageWidth:p.imageWidth,imageHeight:p.imageHeight,imageThumbWidth:p.imageThumbWidth,imageThumbHeight:p.imageThumbHeight}))));
write('favorites/index.html',page('찜한 상품','찜한 상품을 선택해 장바구니로 옮기세요.',`<section class="pagehead list-pagehead title-tab-line title-tab-green"><h1 class="title-tab">찜한 상품</h1></section><section class="section favorites-section compact-list-section"><div class="favorite-summary" role="status" aria-live="polite"><strong data-favorite-summary>찜한 상품 0종</strong><span data-favorite-total></span></div><div id="favorite-import" class="favorite-import" hidden><p></p><button id="favorite-import-button" type="button">목록에 추가</button><button id="favorite-import-dismiss" type="button">취소</button></div><div class="favorite-tools"><input type="hidden" id="favorite-search" value=""><label>정렬 <select id="favorite-sort"><option value="added">담은순</option><option value="name">이름순</option><option value="price-low">가격 낮은순</option><option value="price-high">가격 높은순</option><option value="discount-high">할인율 높은순</option><option value="discount-low">할인율 낮은순</option></select></label></div><div class="favorite-transfer-tools"><label><input type="checkbox" id="favorite-select-all"> 표시 상품 전체 선택</label><button type="button" id="favorite-move-selected" disabled>선택 상품 장바구니로</button><button type="button" id="favorite-move-all">찜 전체 장바구니로</button></div><div id="favorite-list" class="favorite-list"></div><p id="favorite-no-results" class="favorite-empty" hidden>검색 결과가 없습니다.</p><div class="favorite-empty" id="favorite-empty"><p>아직 찜한 상품이 없습니다.</p><a href="/products/">상품 살펴보기</a></div><div class="favorite-actions"><button type="button" id="favorite-clear" class="favorite-clear" hidden>찜 목록 비우기</button><a class="button" href="/shopping/">장바구니 보기</a></div><p id="favorite-message" role="status" aria-live="polite"></p></section>`,'/favorites/'));
write('shopping/index.html',page('장바구니','구매 예정 금액과 쿠팡 표시가의 차액을 확인하고 구매 완료를 체크하세요.',`<section class="pagehead list-pagehead title-tab-line"><h1 class="title-tab">장바구니</h1></section><section class="section favorites-section compact-list-section"><div class="shopping-totals" role="status" aria-live="polite"><div><span>구매 완료 합계</span><strong data-shopping-selected>0원</strong></div><div><span>전체 합계</span><strong data-shopping-total>0원</strong></div><div class="shopping-savings"><span>절약한 금액</span><strong data-shopping-saving>0원</strong></div><div><span>남은 구매금액</span><strong data-shopping-remaining>0원</strong></div></div><div class="shopping-toolbar"><input type="hidden" id="shopping-search" value=""><label class="shopping-sort-label"><span class="sr-only">정렬</span><select id="shopping-sort"><option value="added">담은순</option><option value="name">이름순</option><option value="price-low">가격 낮은순</option><option value="price-high">가격 높은순</option><option value="discount-high">할인율 높은순</option><option value="discount-low">할인율 낮은순</option></select></label><p class="shopping-progress" data-shopping-progress>구매완료 0 / 0종 · 0개</p><button type="button" id="shopping-share" disabled>목록 전달</button></div><div id="shopping-list" class="favorite-list"></div><p id="shopping-no-results" class="favorite-empty" hidden>검색 결과가 없습니다.</p><div class="favorite-empty" id="shopping-empty"><p>구매할 상품이 없습니다.</p><a href="/favorites/">찜 목록에서 상품 옮기기</a></div><div class="favorite-actions"><a class="button" href="/favorites/">찜 목록 보기</a><button type="button" id="shopping-clear-completed">구매 상품 지우기</button><button type="button" id="shopping-clear">장바구니 비우기</button></div><p id="shopping-message" role="status" aria-live="polite"></p></section>`,'/shopping/'));
const decisionBox=p=>{const m=guideMeta[p.slug];return m?`<aside class="guide-decision"><strong>매장에서 이것만 확인하세요</strong><ul>${m.checks.map(check=>`<li>${esc(check)}</li>`).join('')}</ul></aside>`:''};
const factsBox=p=>{
  const fact=guideFacts[p.slug];
  if(!fact)return `<aside class="fact-box"><h2>한눈에 보기</h2><p>${esc(p.summary)}</p><p class="fact-scope">이 글은 구매 판단 방법을 설명합니다. 매장별 판매 여부·가격은 현장 안내를 확인하세요.</p></aside>`;
  return `<aside class="fact-box"><h2>한눈에 보기</h2><p>${esc(fact.answer)}</p><p class="fact-scope"><strong>적용 범위</strong> ${esc(fact.scope)}</p></aside>`;
};
const sourcesBox=p=>{
  const sources=guideFacts[p.slug]?.sources||[];
  if(!sources.length)return p.slug==='compare-unit-prices'?'<aside class="sources"><h2>계산 근거</h2><p>본문의 수식과 가상 숫자로 직접 계산한 예시입니다. 외부 판매가격을 인용하지 않았습니다.</p></aside>':'';
  return `<aside class="sources"><h2>근거와 확인 범위</h2><ul>${sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a> · ${esc(s.publisher)}<p>${esc(s.note)}</p></li>`).join('')}</ul><p>출처의 최신 상태와 개별 상품 표시는 방문 시 다시 확인하세요.</p></aside>`;
};
for(const p of posts){
  const canonical=`/guides/${p.slug}/`;
  const schema=guideFacts[p.slug]&&p.modifiedAt?{'@context':'https://schema.org','@type':'Article',headline:p.title,description:p.summary,dateModified:p.modifiedAt,mainEntityOfPage:origin+canonical,publisher:{'@type':'Organization',name:'PX 구매 가이드',url:origin+'/about/'}}:null;
  write(`guides/${p.slug}/index.html`,page(p.title,p.summary,`<article class="article"><a class="back" href="/guides/">← 구매 가이드</a><span class="eyebrow">PX GUIDE${p.modifiedAt?` · <time datetime="${esc(p.modifiedAt)}">${esc(formatDate(p.modifiedAt))} 수정</time>`:''}</span><h1>${esc(p.title)}</h1>${factsBox(p)}${decisionBox(p)}${p.slug==='px-liquor-vat-exemption'?'':articleFigure(p)}${productGallery(p)}${priceTool(p)}<nav class="contents" aria-label="이 글의 목차"><strong>이 글의 목차</strong><ol>${p.sections.map(([h],i)=>`<li><a href="#part-${i+1}">${esc(h)}</a></li>`).join('')}</ol></nav>${p.sections.map(([h,b],i)=>`<section id="part-${i+1}"><h2>${esc(h)}</h2><p>${esc(b)}</p></section>`).join('')}${sourcesBox(p)}<aside class="article-note"><strong>구매 전 확인</strong><p>상품의 입고, 가격, 구성, 사용 조건은 매장과 시기에 따라 달라질 수 있습니다. 방문하는 매장의 안내와 상품 표시를 최종 기준으로 확인하세요.</p></aside>${related(p)}<a class="button" href="/guides/">다른 구매 가이드 보기</a></article>`,canonical,schema));
}
write('about/index.html',page('사이트 소개','PX 구매 가이드의 운영 원칙, 자료 출처와 수정 방법입니다.',`<section class="pagehead"><span class="eyebrow">ABOUT</span><h1>사이트 소개</h1><p>PX 구매 전에 확인할 질문과 비교 방법을 독립적으로 정리합니다.</p></section><article class="article"><h2>운영 범위</h2><p>이 사이트는 PX 운영기관과 제휴하지 않은 독립 안내 사이트입니다. 매장의 재고·가격·이용 자격을 실시간으로 조회하지 않습니다. 확인되지 않은 월별 할인은 게시하지 않습니다.</p><h2>자료와 판단을 구분합니다</h2><p>운영기관 공지와 제조사 상품 표시에서 확인한 내용은 문서 안에 출처와 적용 범위를 적습니다. 단위가격 계산과 장바구니 예시는 자체 설명으로 표시하며 실제 판매가격으로 제시하지 않습니다. 직접 써보지 않은 상품을 사용 후기나 효과 검증으로 소개하지 않습니다.</p><h2>날짜와 수정</h2><p>글에 보이는 수정일은 해당 원고를 실제로 고친 날짜입니다. 게시일이나 외부 자료의 확인일을 알 수 없으면 임의로 만들지 않습니다. 출처의 내용이 바뀌거나 오류가 확인되면 본문과 확인 범위를 고치고 수정일을 갱신합니다.</p><h2>오류 제보와 이미지</h2><p><a href="/contact/">문의 페이지</a>로 글 주소, 수정할 문장, 근거 링크를 보내 주세요. 확인 후 정정합니다. 외부 상품 이미지는 상품 식별에 사용하지만 이미지 제공 브랜드가 이 사이트를 승인하거나 제휴했다는 뜻은 아닙니다.</p><h2>광고와 독립성</h2><p>현재 광고는 설정되어 있지 않습니다. 향후 광고가 게재되면 안내 콘텐츠와 구분해 표시하겠습니다.</p></article>`,'/about/'));
write('contact/index.html',page('문의','PX 구매 가이드의 이용 문의와 개선 의견을 이메일로 보내 주세요.',fs.readFileSync('content/feedback.html','utf8'),'/contact/'));
const faqContent=`<section class="pagehead"><span class="eyebrow">FAQ</span><h1>자주 묻는 질문 (FAQ)</h1><p>PX 영외마트 이용 방법, 시중가 비교 기준, 할인 혜택 등 자주 묻는 질문을 모았습니다.</p></section><article class="article faq-article"><section class="faq-group"><h2>PX 이용 및 방문 자격</h2><details class="faq-card" open><summary><strong>영외마트(PX)는 누구나 이용할 수 있나요?</strong></summary><div class="faq-answer"><p>영외마트(군 마트)는 국방부 복지 규정에 따라 <strong>군인, 군무원, 10년 이상 복무 후 전역한 예비역, 국가유공자, 보훈대상자 및 그 직계가족</strong>(배우자, 본인 및 배우자의 직계존비속)만 이용할 수 있습니다. 방문 시 신분증 및 자격 증명서류(밀리패스, 국가유공자증, 가족관계증명서 등) 확인이 필요합니다.</p></div></details><details class="faq-card" open><summary><strong>방문 전 무엇을 확인해야 하나요?</strong></summary><div class="faq-answer"><p>영외마트는 매장마다 운영 시간, 점심시간(브레이크 타임), 정기 휴무일(일요일 및 공휴일 휴무 등), 인기 상품 입고 요일이 다릅니다. 상단 메뉴의 <strong>[가까운 PX]</strong> 탭에서 전국 영외마트의 위치, 전화번호, 주소 정보를 확인하신 후 방문하시는 것을 권장합니다.</p></div></details></section><section class="faq-group"><h2>가격 및 시중가 비교 안내</h2><details class="faq-card" open><summary><strong>시중가(쿠팡 등) 및 할인율은 어떻게 계산되나요?</strong></summary><div class="faq-answer"><p>PX 가이드는 주요 온라인 마켓(쿠팡 로켓배송, 공식 브랜드 스토어 등)의 실제 유통 가격을 정기적으로 수집·대조합니다. 동일 상품(동일 용량·구성)을 기준으로 PX 면세가와 시중 최저가를 비교하여 실제 절약 금액과 체감 할인율을 계산해 제공합니다.</p></div></details><details class="faq-card" open><summary><strong>실제 현장 판매가격과 다를 수 있나요?</strong></summary><div class="faq-answer"><p>국군복지단 및 제조사의 납품 단가 조정, 패키지 리뉴얼, 기간 한정 특가 행사에 따라 현장 판매가격이 소폭 변동될 수 있습니다. 본 사이트는 독립 안내 사이트로서 이용자 편의를 돕는 참고 정보이며, 최종 결제 금액은 매장 매대의 공식 가격표를 기준으로 합니다.</p></div></details></section><section class="faq-group"><h2>이달의 할인 및 인기 상품</h2><details class="faq-card" open><summary><strong>‘이달의 할인’ 정보는 언제 업데이트되나요?</strong></summary><div class="faq-answer"><p>매월 국군복지단의 월간 정기 할인 행사 및 신규 프로모션 발표에 맞추어 즉시 갱신됩니다. <strong>[이달의 할인]</strong> 탭에서 화장품, 건강식품, 가공식품 등 품목별 할인율과 행사 기간을 한눈에 살펴보실 수 있습니다.</p></div></details><details class="faq-card" open><summary><strong>PX에서 가장 인기 있는 추천 품목은 무엇인가요?</strong></summary><div class="faq-answer"><p>닥터지(블랙스네일 크림 등), AHC, 참존, 독도 토너 등 기능성 스킨케어 화장품과 정관장 홍삼정에브리타임, 종근당 락토핏 등 건강기능식품류가 시중가 대비 최대 70~80% 이상 저렴하여 가장 인기가 많습니다. <strong>[전체 상품]</strong>에서 '할인율순' 정렬을 활용해 보세요.</p></div></details></section><section class="faq-group"><h2>장바구니, 찜 및 목록 전달 기능</h2><details class="faq-card" open><summary><strong>찜한 상품과 장바구니 목록은 어디에 저장되나요?</strong></summary><div class="faq-answer"><p>사용하시는 기기의 브라우저 로컬 저장소(LocalStorage)에 안전하게 저장됩니다. 회원가입이나 로그인 없이도 언제든 목록을 확인하고 수정하실 수 있습니다.</p></div></details><details class="faq-card" open><summary><strong>PX 방문자에게 구매 부탁 목록을 전달할 수 있나요?</strong></summary><div class="faq-answer"><p>장바구니 페이지 하단의 <strong>[구매 목록 전달하기]</strong> 버튼을 누르면 담아둔 품목명, 수량, 예상 금액이 정돈된 텍스트로 클립보드에 자동 복사됩니다. 카카오톡이나 문자 메시지로 가족, 지인에게 바로 전달할 수 있습니다.</p></div></details></section><section class="faq-group"><h2>홈 화면 추가 (PWA 앱 설치)</h2><details class="faq-card" open><summary><strong>스마트폰 바탕화면에 앱처럼 설치하려면 어떻게 하나요?</strong></summary><div class="faq-answer"><p>화면 우측 상단의 <strong>[홈 추가]</strong> 버튼을 누르시면 사용 중인 기기 환경(안드로이드 Chrome, 아이폰 Safari 등)에 최적화된 안내가 나타납니다. 홈 화면에 추가하시면 주소창 없이 앱처럼 더욱 넓고 쾌적하게 사용하실 수 있습니다.</p></div></details></section><section class="faq-group"><h2>문의 및 정보 수정 요청</h2><details class="faq-card" open><summary><strong>가격 오류 제보나 사이트 개선 건의는 어디로 하나요?</strong></summary><div class="faq-answer"><p>하단의 <strong>[문의]</strong> 메뉴를 통해 의견을 남겨주시면 정기적으로 확인하여 신속하게 정보 수정 및 사이트 기능 개선에 반영하고 있습니다.</p></div></details></section></article>`;
write('faq/index.html',page('자주 묻는 질문 (FAQ)','PX 영외마트 이용 방법, 시중가 비교 기준, 이달의 할인 등 자주 묻는 질문과 답변 안내입니다.',faqContent,'/faq/'));
write('privacy/index.html',page('개인정보 안내','PX 구매 가이드의 현재 데이터 처리 상태입니다.',`<section class="pagehead"><span class="eyebrow">PRIVACY</span><h1>개인정보 안내</h1><p>현재 사이트의 기능을 기준으로 설명합니다.</p></section><article class="article"><h2>현재 제공하는 기능</h2><p>문의는 이메일로만 받으며, 회원가입이나 결제 기능은 제공하지 않습니다. 단위가격 계산기는 입력값을 방문자의 브라우저에서 계산하며 서버로 전송하지 않습니다.</p><h2>찜 목록</h2><p>찜한 상품의 식별자와 수량·구매 체크 상태는 이 브라우저의 로컬 저장소에 보관됩니다. 계정이나 서버에 동기화하지 않으며, 찜 해제 또는 브라우저 데이터 삭제로 지울 수 있습니다. 공유 링크를 직접 만들면 상품 식별자와 수량이 링크에 담깁니다. 링크를 받은 사람은 그 정보를 볼 수 있으므로 공유 대상을 확인하세요. 다른 기기로는 링크를 통해 목록을 가져올 수 있습니다.</p><h2>현위치 거리 계산</h2><p>가까운 PX에서 위치 사용을 허용하면 브라우저 안에서 매장까지의 직선거리를 계산합니다. 현위치는 서버로 전송하거나 저장하지 않으며 화면을 닫으면 유지되지 않습니다.</p><h2>이전 문의 게시판</h2><p>공개 문의 게시판은 종료되었으며, 기존 게시물은 공개 화면에서 더 이상 제공하지 않습니다. 이전에 작성한 글과 관련된 문의도 아래 이메일로 보내 주세요.</p><h2>익명 관심 집계</h2><p>상품을 찜하거나 장바구니에 처음 추가할 때 상품 식별자와 추가 종류를 보내 상품별·일별 횟수만 집계합니다. 같은 브라우저에서 같은 날 중복 전송을 줄이기 위한 표시만 로컬 저장소에 남깁니다. 찜 목록과 장바구니 목록 자체는 서버로 전송하지 않으며 계정에 저장하지 않습니다. 관심 집계에는 이름·이메일·IP 주소를 저장하지 않습니다.</p><h2>오늘 방문자 집계</h2><p>오늘 방문자 수는 한국 시간 자정을 기준으로 같은 브라우저를 하루 한 번 집계합니다. 중복 집계를 막기 위해 무작위 식별자 쿠키를 사용하며 자정에 만료됩니다. 집계에는 날짜와 무작위 식별자만 저장하며 이름·이메일·IP 주소를 저장하지 않습니다. 쿠키를 삭제하거나 다른 브라우저를 사용하면 별도 방문으로 집계될 수 있습니다.</p><h2>이메일 문의</h2><p><a href="mailto:honglabai@gmail.com">honglabai@gmail.com</a>으로 이메일을 보내면 발신 주소와 메시지를 문의 확인 및 답변에 사용합니다. 문의에 필요한 정보만 보내 주세요. 문의 기록의 보관 또는 삭제에 대해서는 같은 주소로 문의할 수 있습니다.</p><h2>외부 상품 이미지</h2><p>일부 글은 제조사 또는 브랜드의 이미지 서버에서 사진을 직접 표시합니다. 해당 사진이 있는 페이지를 열면 브라우저가 이미지 서버에 접속하므로 IP 주소와 접속 관련 기술 정보가 해당 서버에 전달될 수 있습니다. 상품별 연결 주소는 해당 글의 공식 상품 페이지에서 확인할 수 있습니다.</p><h2>호스팅 과정의 기록</h2><p>사이트 제공을 위해 호스팅 사업자가 접속 관련 기술 정보와 로그를 처리할 수 있습니다. 구체적인 보관 기간과 처리 주체는 운영자 확인 후 보완할 예정입니다.</p><h2>광고를 시작할 경우</h2><p>Google AdSense를 사용하기 전에 Google 서비스의 쿠키·데이터 처리, 관련 동의 관리를 확인해 이 안내를 갱신하겠습니다. 현재 광고 코드는 설치되어 있지 않습니다.</p></article>`,'/privacy/'));
write('admin/coupang-prices/index.html',page('쿠팡 가격 검토','운영자 가격 검토 화면입니다.',`<section class="pagehead"><span class="eyebrow">OWNER REVIEW</span><h1>쿠팡 가격 검토</h1><p>관찰값의 출처와 가격 변동을 확인한 뒤 결정하세요.</p></section><section class="price-review" aria-labelledby="price-review-status"><p id="price-review-status" role="status">검토 목록을 불러오는 중…</p><div id="price-review-list"></div><nav class="price-review-pages" aria-label="가격 검토 페이지"><button id="price-review-prev" type="button" disabled>이전</button><span id="price-review-page" aria-live="polite">0 / 0</span><button id="price-review-next" type="button" disabled>다음</button></nav></section><script src="/price/admin-ui.js" defer></script>`,'/admin/coupang-prices/').replace('</head>','<meta name="robots" content="noindex,nofollow"></head>'));
